mapper.select:
SELECT id, user_id, target_id, target_type, create_time
FROM ugc_like
WHERE user_id    = #{userId}
  AND target_id   = #{targetId}
  AND target_type = #{targetType}
LIMIT 1

mapper.delete:
DELETE FROM ugc_like
WHERE user_id    = #{userId}
  AND target_id   = #{targetId}
  AND target_type = #{targetType}
